<script setup lang="ts">import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { useI18n } from 'vue-i18n';import * as echarts from 'echarts/core';import { MapChart } from 'echarts/charts';import { TooltipComponent,VisualMapComponent } from 'echarts/components';import { CanvasRenderer } from 'echarts/renderers';import StatusTable from '../components/StatusTable.vue';import { useStatusStore } from '../stores/status';echarts.use([MapChart,TooltipComponent,VisualMapComponent,CanvasRenderer]);const {t}=useI18n();const store=useStatusStore();const grouped=ref(localStorage.getItem('santaizi-status-grouped')!=='0'),mapOpen=ref(false),mapNode=ref<HTMLElement>();let chart:echarts.ECharts|undefined
const all=computed(()=>store.servers);function toggle(){grouped.value=!grouped.value;localStorage.setItem('santaizi-status-grouped',grouped.value?'1':'0')}async function showMap(){mapOpen.value=true;setTimeout(async()=>{const geo=await fetch('/static/theme-server-status/maps/santaizi.world.geo.json').then(v=>v.json());echarts.registerMap('santaizi-world',geo);const counts=new Map<string,number>();for(const row of store.servers){const code=String(row.host?.CountryCode||row.host?.country_code||'').toUpperCase();if(code)counts.set(code,(counts.get(code)||0)+1)}chart=echarts.init(mapNode.value!);chart.setOption({tooltip:{trigger:'item'},visualMap:{min:0,max:Math.max(1,...counts.values()),left:20,bottom:20,inRange:{color:['#dbeafe','#2563eb']}},series:[{type:'map',map:'santaizi-world',roam:true,data:[...counts].map(([name,value])=>({name,value}))}]})},50)}function closeMap(){chart?.dispose();mapOpen.value=false}onMounted(store.connect);onBeforeUnmount(store.stop)
</script><template><div class="status-container"><div class="status-toolbar"><span :class="['connection-state',store.connected?'connected':'']"><i></i>{{store.loadError?t('loadFailed'):store.connected?t('liveConnected'):t('reconnecting')}}</span><span/><button v-if="store.loadError" @click="store.load"><i class="ri-refresh-line"></i>{{t('refresh')}}</button><button @click="showMap"><i class="ri-earth-line"></i>{{t('worldMap')}}</button><button @click="toggle"><i :class="grouped?'ri-list-check-2':'ri-folder-chart-line'"></i>{{t(grouped?'flatView':'groupView')}}</button></div><template v-if="grouped"><StatusTable v-for="group in store.groups" :key="group.name" :title="group.name" :servers="group.items"/></template><StatusTable v-else :servers="all"/><dialog :open="mapOpen" class="map-dialog"><header><h2><i class="ri-earth-line"></i>{{t('worldMap')}}</h2><button @click="closeMap"><i class="ri-close-line"></i></button></header><div ref="mapNode" class="world-map"/></dialog></div></template>
